import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Custom CUDA ReLU
relu_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void relu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        output[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor relu_cuda(torch::Tensor input) {
    auto output = torch::zeros_like(input);
    int size = input.numel();
    int threads = 256;
    int blocks = (size + threads - 1) / threads;

    relu_kernel<<<blocks, threads>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}
""".strip()

relu_cpp_source = "torch::Tensor relu_cuda(torch::Tensor input);"

custom_relu_op = load_inline(
    name="custom_relu_op",
    cpp_sources=relu_cpp_source,
    cuda_sources=relu_source,
    functions=["relu_cuda"],
    verbose=False
)

class CustomReLU(nn.Module):
    def __init__(self, relu_op):
        super().__init__()
        self.relu_op = relu_op

    def forward(self, x):
        return self.relu_op.relu_cuda(x)

class ModelNew(nn.Module):
    def __init__(self, input_channels, stages, block_widths, output_classes):
        super().__init__()
        self.stages = stages
        self.block_widths = block_widths

        layers = []
        current_channels = input_channels

        for _ in range(stages):
            layers.append(self._make_stage(current_channels, block_widths[_]))
            current_channels = block_widths[_]

        self.feature_extractor = nn.Sequential(*layers)
        self.fc = nn.Linear(block_widths[-1], output_classes)

    def _make_stage(self, in_channels, out_channels):
        return nn.Sequential(
            nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1),
            nn.BatchNorm2d(out_channels),
            CustomReLU(custom_relu_op),
            nn.Conv2d(out_channels, out_channels, kernel_size=3, padding=1),
            nn.BatchNorm2d(out_channels),
            CustomReLU(custom_relu_op),
            nn.MaxPool2d(kernel_size=2, stride=2)
        )

    def forward(self, x):
        x = self.feature_extractor(x)
        x = torch.mean(x, dim=[2, 3])
        x = self.fc(x)
        return x

def get_inputs():
    batch_size = 8
    input_channels = 3
    image_height, image_width = 224, 224
    return [torch.randn(batch_size, input_channels, image_height, image_width)]

def get_init_inputs():
    input_channels = 3
    stages = 3
    block_widths = [64, 128, 256]
    output_classes = 10
    return [input_channels, stages, block_widths, output_classes]
